//"No tint" value of octSprite_t.Data0. Deliberately WHITE: multiplying a palette by white is the
//identity, so "not tinted" and "tinted white" are the same picture and no sentinel semantics exist
//-- the renderer merely skips the (identity) conversion. Every sprite is born with this value
//(OCT_add), which frees 0x0000 to be an honest black tint.
#define OCT_TINT_NONE 0xFFFF

//How octSprite_t.Data0 is combined with the sprite's colours (octSprite_t.Blend, set by
//OCT_tint_mode). All of them are per-channel and SATURATING -- adding white to a grey-green gives
//white, it does not wrap. MUL is 0 because a sprite is born zeroed, so an untouched sprite keeps the
//multiply that predates this field. What each costs on which art: OCT_RENDER_rasterize.
#define OCT_BLEND_MUL       0       //dst = src * tint            -- Photoshop Multiply; exact recolour of coverage art
#define OCT_BLEND_ADD       1       //dst = min(src + tint, max)  -- flash / glow / lighten
#define OCT_BLEND_SUB       2       //dst = max(src - tint, 0)    -- darken towards black
#define OCT_BLEND_SCREEN    3       //dst = max - (max-src)*(max-tint)/max  -- Photoshop Screen
#define OCT_BLEND_HUE       4       //rotate the hue about the grey axis, keeping brightness; Data0 is a step of OCT_HUE_STEPS, not a colour

//The Data0 that leaves a sprite untouched in a mode, which the renderer skips converting: white for
//MUL, black for ADD/SUB/SCREEN, a zero rotation for HUE. Every sprite is born white (OCT_TINT_NONE),
//so one switched to ADD without a colour would turn solid white: OCT_tint_mode writes both together.
#define OCT_BLEND_IDENTITY(mode) ((mode) == OCT_BLEND_MUL ? (uint16_t)OCT_TINT_NONE : (uint16_t)0x0000)

