//Just an id, but also index into OCT_TWISTS table
typedef int octTwistId_t;

enum TWIST_ID { TOP_CCW  = 0, TOP_CW  = 1,  FRONT_CCW = 2, FRONT_CW = 3,  RIGHT_CCW  = 4,  RIGHT_CW  = 5, //CCW or CW is determined looking from outside of the cube
                BACK_CCW = 6, BACK_CW = 7,  LEFT_CCW  = 8, LEFT_CW  = 9,  BOTTOM_CCW = 10, BOTTOM_CW = 11 };

enum AXIS_ID { AXIS_NONE = 0, AXIS_X = 1, AXIS_Y = 2, AXIS_Z = 3};

const octTwistId_t OCT_TWIST_HALF = 12, OCT_TWIST_ALL = 24, OCT_TWIST_DOUBLE = 32, OCT_TWIST_PRE = 64, OCT_TWIST_NONE = -1;
//0..11 - usual twists
//12..23 - half twists
//24 - consider everything changed
//32 - currently only internal use, splits to a pair of usual twists
//64..69 - PRETWIST: a twist that has STARTED, carried as 64 + PLANE over the existing
//         PKT_CMD_TWIST so the wire and PKT_SIZES stay unchanged -- the same idiom as the
//         launch origin packed into CMD_APP's spare bits. The apply arm routes these to
//         OCT_on_pretwisted and touches neither topology nor sprites.
//         The payload is the SIDE being turned (0..5), and deliberately NOT a winding: the
//         plane follows from WHICH modules fell silent and is solid, whereas a direction can
//         only be guessed from the rotation seen so far and is wrong often enough to be unusable
//         in a game. An app that needs the direction waits for on_twisted, which is authoritative.
//-1 - no changes


//OCT_anim restart parameter []
typedef int octSeqRestart_t;

const octSeqRestart_t OCT_SEQ_RESTART = 1, OCT_SEQ_REVERSE = -1, OCT_SEQ_REFRESH = 0;

