//Only used to pass bitmap info to the app side
#pragma pack(push, 4)
typedef struct
{
    char        Name[24];               //Sprite name in pack
    float       PivotX, PivotY;         //Pivot point relative to top left corner
    float       Bx, By, Bw, Bh;         //Bounding geometry
    uint32_t    Tags;                   //Additional data about image
    int16_t     W, H;                   //Width and height in screen pixels
    int16_t     Number;
    uint8_t     Group;
    uint8_t     Type;
} octBmpInfo_t;
#pragma pack(pop)


//Scene object, can be extended on the application's side. Size MUST be multiple of 4.
#pragma pack(push, 4)
typedef struct
{
    int         Idx;                            //MUST be the first 4 bytes. Unique key.
    int         Parent;                         //MUST be the second 4 bytes. Index of parent object, or zero.
    int         Order;                          //MUST be the third 4 bytes. Internal key for sorting purposes.
    octTm_t     Tm;                             //Local transform
    
    uint32_t    Mask:24,                        //Bitmask of which cameras are not allowed to draw this object
                DynPal:8;                       //Offset of dynamic palette colors. Zero means use default (bmp's) palette. Each +1 offset means +32 array items (ints).
    
    int16_t     Zw, Zh;                         //This is object's covered zone, not bitmap's: i.e. label keeps here it's text zone dimensions
    
    uint8_t     Lut;                            //Bmp index for special effects
    int8_t      Param1;                         //
    int8_t      Param2;                         //
    int8_t      Param3;                         //

    uint16_t    Data0;                          //RGB565 tint of the sprite (OCT_TINT_NONE = draw with the baked palette; the colour of procedural text/circle/line). Set at creation by OCT_add
    uint8_t     Data1, Data2;

    uint32_t    Tags;                           //Custom app-related bitmask of TAG_* literals; usually set when map is loading
    int16_t     Number;                         //Custom number; usually some constant from map
    uint16_t    AgeTicks;                       //Lifetime
    uint16_t    AgeMark;                        //When autokill is true, this marks age when sprite will be deleted; when false - marks any app-related period
    uint16_t    Twistable:1,                    //Will be moved with twist in corresponding direction (by default object ignores any twists)
                Hidden:1,                       //Won't be rendered
                Autokill:1,
                ShowCollider:1,
                FlipH:1,
                FlipV:1,
                Label:2,
                Letter:1,
                Fresh:1,
                Loop:1,
                PingPong:1,
                Line:1,
                Keyed:1;                        //PROCEDURAL_CUSTOM whose picture is a pure function of DrawKey


    //Frame animation
    int16_t     FrameFrom, FrameTo;             //Actual frame animation sequence
    
    int16_t     Frame;
    uint8_t     FramesCooldown;                 //How many frames to wait after reaching FrameTo
    uint8_t     FAccum;
    
    int8_t      FrameRate;
    uint8_t     Reverse:1, Paused:1, InDelay:1, InCooldown:1, OnCooldown:1, OnEnd:1;
    uint8_t     Type;                           //Custom and app-related type of the object; usually set when map is loading to TYPE_* constant
    uint8_t     Name;                           //Id that allows to bind app logic to this specific object; usually set to a NAME_* constant when map is loading
    
    uint8_t     Group;                          //Id that marks subset of the scene; usually set to a GROUP_* constant when map is loading
    int8_t      Layer;                          //Z-order - higher value layers are drawn over lower ones
    uint8_t     Transp:5;                       //Transparency, actual range is [0 .. 31 (OCT_TRANSP_MAX)]
    uint8_t     Procedural;                     //Special draw function, also could repurpose some other fields

    uint16_t    DrawKey;                        //Keyed sprite's picture input, owner-written; 0 elsewhere
    uint8_t     Blend;                          //How Data0 is combined with the palette: OCT_BLEND_* (0 = MUL, the behaviour that predates this field). Set with Data0 by OCT_tint_mode
    uint8_t     Reserved[9];                    //To add features without breaking older apps compatibility
} octSprite_t;
#pragma pack(pop)


#pragma pack(push, 4)
typedef struct
{
    uint64_t Guid1, Guid2;
    uint32_t Type;                              //octEntryType_t
    uint8_t  Name[OCT_SOFTWARE_NAME_MAXLEN];
} octEntryInfo_t;
#pragma pack(pop)


//Where the tap being handled came from (the tap_source import): the module struck, the loudest on the face it landed on,
//that module's screen there (its screen id is 3 * Module + Screen), how many modules felt it push the way most did, two
//or more by default, that module's impact strength (its raw-jerk peak along its push axis, 128 at 2000 LSB of +-2 g, 16
//more per doubling), the plane on_tap names, the axis the impact pushed along, an AXIS_ID signed by its direction
//(-AXIS_Y for a tap on the top), and the scene quad (vid 0..23) that screen showed, -1 when unbound. The same on all
//eight modules. Grows at the tail, but octGestureProbe_t carries it mid-struct: a new field takes Padding first.
//Quad took Padding[0], so firmware before it reads 0 there
#pragma pack(push, 4)
typedef struct
{
    uint8_t Module, Screen, Agreeing, Amplitude;
    int8_t  Plane;
    int8_t  Axis;
    int8_t Quad;
    uint8_t Padding[1];
} octTapSource_t;
#pragma pack(pop)


//The cube's orientation (the cube_pose and cube_pose_visual imports) and a module's (module_pose). Quaternions are
//w, x, y, z and turn a vector given in the first frame's axes into the second's. The world's z points up; its zero of yaw
//is the leader's heading when its filter started and drifts with the gyro, so a game may rely on tilt, never on a north.
//Each struct grows at the tail: `size` is what the engine filled. Contract and frames: docs/knowledge/cube_pose.md
#define OCT_POSE_VALID              (1u << 0)   //the pose holds a value; nothing else in the struct means anything without it
#define OCT_POSE_TWIST_OPEN         (1u << 1)   //a twist is turning `plane`: the turn about that axis is held where it was
#define OCT_POSE_BIAS_CALIBRATED    (1u << 2)   //the gyro's bias has been measured at rest since the leader's boot (cube_pose_visual: and this module's)
#define OCT_POSE_LOCAL              (1u << 3)   //cube_pose_visual only: this module's own pose, anchored on the leader's; clear when it answered with cube_pose
#pragma pack(push, 4)
typedef struct
{
    uint16_t size;              //sizeof the struct the engine filled
    uint8_t  flags;             //OCT_POSE_*
    int8_t   plane;             //AXIS_X..AXIS_Z while OCT_POSE_TWIST_OPEN, -1 otherwise
    float    q[4];              //cube axes to the world
    float    gravity_cube[3];   //the world's down in cube axes, a unit vector: as OCT_TM_gravity_* read it, from the same pose
    float    rate_cube[3];      //the turn rate in cube axes, deg/s, the gyro's bias taken out
    uint32_t apply_tick;        //the tick the leader's broadcast applied on
    uint16_t age_ms;            //cube_pose: from the leader's sample to that tick's end, which the pose is predicted over; cube_pose_visual: of this module's newest sample
    uint16_t reserved;
} octCubePose_t;

typedef struct
{
    uint16_t size;              //sizeof the struct the engine filled
    uint8_t  module;            //the module asked for, 0-7
    uint8_t  flags;             //OCT_POSE_VALID: the cube pose holds one and all three screens are bound; OCT_POSE_TWIST_OPEN as the cube pose's
    float    q[4];              //module axes to the world: x out of screen 0, y into screen 1, z out of screen 2
    int8_t   corner[3];         //the cube corner it sits in: +1 or -1 on each cube axis, 0 while unbound
    int8_t   sides[3];          //the side (0-5, as OCT_TM_top_side numbers them) each of its screens 0-2 shows, -1 while unbound
    uint8_t  reserved[2];
} octModulePose_t;
#pragma pack(pop)
OCT_STATIC_ASSERT(sizeof(octCubePose_t) == 52  &&  sizeof(octModulePose_t) == 28, "the pose structs are app ABI: they only grow at the tail");


//One step of the 16-bit biased LCG behind OCT_random and OCT_random_local, on whichever state the caller owns.
//Here because an app on firmware without random_local runs it on a state of its own (oct_app_module.h), and every
//stream must draw the same way. Never gives dmax (unless it equals dmin).
static inline int OCT_random_draw(uint32_t* state, int dmin, int dmax)
    {
        *state = (214013*(*state)+2531011);
        return dmin + (int)((dmax - dmin) * ((*state>>16)&0x7FFF) / (float)(0x7FFF + 1));
    }
